class Unit {
  static suffix = " units";

  static show(amount) {
    return `${amount}${this.suffix}`;
  }
}

class Metres extends Unit {
  static suffix = "m";
}

class Count extends Unit {}

console.log(Metres.show(5));
console.log(Count.show(5));
console.log(Object.hasOwn(Count, "show"));
console.log(Object.getPrototypeOf(Metres) === Unit);
